// Додзё КАЙТАКА — зал клуба. Первый уровень и хаб между главами.
//
// Это ОПИСАНИЕ, а не код: arena.js читает его и расставляет всё сам.
// Двигать предметы, добавлять новые и менять свет можно прямо здесь,
// не заглядывая в отрисовку.
//
// Оси: X — вдоль зала, Y — высота, Z — глубина. Татами лежит от -D/2 до D/2.

import { C } from "../../scene/palette.js";
import { BELTS } from "../belts.js";

const BACK = -8.5;         // плоскость задней стены
const D = 11;              // глубина татами

export const DOJO = {
  id: "dojo",
  name: "ДОДЗЁ",
  jp: "道場",
  tip: "Стрелки — движение · J — цуки, два подряд дают связку · K — гери · L — блок · T — режим",

  // Режим движения (fight/moves.js). Здесь отработка на макиварах — это
  // кихон, а не поединок: боец ходит свободно и поворачивается к снаряду.
  // В кумитэ взгляд заперт, и к макиваре было бы не повернуться.
  mode: "training",

  // ЗАДАНИЕ ПЕРВОГО УРОВНЯ.
  //
  // Всё, что можно подкрутить, лежит здесь: число снарядов, ударов на
  // каждый, время и слова сэнсэя. Логику этапа править не нужно.
  task: {
    kind: "makiwara",
    hits: 20,               // ударов на каждую макивару
    seconds: 60,
    reach: 1.35,            // с какого расстояния удар засчитывается, м

    // Сэнсэй объясняет отсюда, потом обходит зал по этому прямоугольнику.
    // Обход идёт против часовой стрелки — его клип поворота уводит влево.
    sensei: { x: 0, z: -5.6 },
    patrol: { x0: -13, x1: 13, z0: -6.4, z1: 6.4 },

    // Слова сэнсэя. {имя} подставляется само.
    brief: [
      "ОСУ, {имя}!",
      "Сегодня — макивара. Четыре снаряда.",
      "Двадцать ударов на каждый. На всё — одна минута.",
      "Бей от бедра. Начали!"
    ],
    win:  "ОСУ! Хорошая работа.",
    lose: "Время вышло. Ещё раз — с начала."
  },

  // Четыре макивары для задания стоят на татами, до них можно дойти.
  // Те, что у стены, — обстановка, они вне зоны боя.
  targets: [
    { x: -7.5, z: -3.0 },
    { x: -2.5, z: -3.0 },
    { x:  2.5, z: -3.0 },
    { x:  7.5, z: -3.0 }
  ],

  length: 64,              // зал вытянут вдоль X: бой идёт вдоль него
  depth: D,
  wallHeight: 4.4,

  // Тёплый свет из окон под потолком. Солнце светит слева-сверху,
  // чтобы тени падали вправо и не закрывали бойца от камеры.
  light: {
    bg: 0x1a1c26,
    sky: 0xd8dcc4,
    ground: C.tatami,
    ambient: 1.05,
    sun: 0xffe9c4,
    sunPower: 2.3,
    sunPos: [-9, 15, 7],
    fogNear: 30,
    fogFar: 78
  },

  props: [
    // Знамя клуба в центре задней стены — камидза, место чести в додзё.
    { type: "banner", x: 0, y: 2.5, z: BACK + 0.06, w: 2.0, h: 2.6, logo: true },

    // Окна по верху стены. Свет и ритм: без них стена читается как забор.
    ...[-26, -19, -12, 12, 19, 26].map(x =>
      ({ type: "window", x, y: 3.1, z: BACK + 0.05, w: 1.9, h: 1.5 })),

    // Стойка с поясами рядом со знаменем — вся лестница пути на виду.
    { type: "beltRack", x: -6.4, y: 2.6, z: BACK + 0.08,
      belts: BELTS.filter(b => !b.stripe).map(b => b.color) },

    // Снаряды для задания — стоят на татами, до них можно дойти.
    { type: "makiwara", x: -7.5, y: 0, z: -3.0, target: 0 },
    { type: "makiwara", x: -2.5, y: 0, z: -3.0, target: 1 },
    { type: "makiwara", x:  2.5, y: 0, z: -3.0, target: 2 },
    { type: "makiwara", x:  7.5, y: 0, z: -3.0, target: 3 },

    // Обстановка у стены: до неё не дойти, она для вида.
    { type: "bag",      x: -11.5, y: 0, z: BACK + 1.5 },
    { type: "bag",      x: -14.2, y: 0, z: BACK + 1.5 },
    { type: "makiwara", x: 21.0, y: 0, z: BACK + 1.3 },
    { type: "bag",      x: -24.0, y: 0, z: BACK + 1.5 },

    // Скамьи для ожидающих своей очереди.
    { type: "bench", x: -3.4, y: 0, z: D / 2 + 1.6 },
    { type: "bench", x:  3.4, y: 0, z: D / 2 + 1.6 },
    { type: "bench", x: 16.5, y: 0, z: D / 2 + 1.6 },
    { type: "bench", x:-18.5, y: 0, z: D / 2 + 1.6 },

    // Потолочные балки. Дают ощущение зала, а не открытой площадки,
    // и отмечают, сколько пройдено вдоль татами.
    ...[-28, -21, -14, -7, 0, 7, 14, 21, 28].map(x =>
      ({ type: "beam", x, y: 4.2, z: -1.5, len: 17 }))
  ]
};
